const list=$('#community-list');list.innerHTML=data.communities.length?data.communities.map(c=>`<article class="panel community-card"><div><span class="eyebrow">${esc(c.area)} · ${c.members} members</span><h2>${esc(c.name)}</h2><p>${esc(c.topic)}</p></div>${me.role==='operator'?'Operator review view':c.joined?`<button class="button primary" data-community-open="${esc(c.id)}">Open chat</button>`:`<button class="outline-button" data-community-join="${esc(c.id)}">Join community</button>`}</article>`).join(''):'<section class="panel empty-state">No approved communities yet. Request one with a clear local purpose.</section>';
