async function renderCommunityChat(id){selectedCommunity=id;const page=$('#community-chat-page'),posts=await api(`/api/communities/${encodeURIComponent(id)}/posts`),community=(await api('/api/communities')).communities.find(c=>c.id===id);if(!community?.joined){toast('Join this group before opening its chat.','warning');showView('community');return}page.innerHTML=`<div class="page-heading chat-page-heading"><div><div class="eyebrow">COMMUNITY GROUP CHAT</div><h1>${esc(community.name)}</h1><p>${esc(community.topic)} · ${esc(community.area)}</p></div><button type="button" class="outline-button" data-back-community>← All groups</button></div><section class="panel community-chat-page-panel"><p class="assumption-note">Keep personal health, identity, contact, and payment details private in group chat.</p><div class="community-posts">${posts.map(p=>`<article class="community-post"><b>${esc(p.author||'Member')}</b><p>${esc(p.message)}</p><small>${new Date(p.created_at).toLocaleString()}</small></article>`).join('')||'<p class="empty-state">No messages yet. Say hello to the group.</p>'}</div><form id="community-post-form" class="form-grid"><label class="full-field">Message<textarea name="message" maxlength="1500" required placeholder="Write a supportive message"></textarea></label><div class="full-field"><button class="button primary">Send message</button></div></form></section>`;$('#community-post-form').onsubmit=async e=>{e.preventDefault();const message=new FormData(e.currentTarget).get('message');try{await api(`/api/communities/${encodeURIComponent(id)}/posts`,{method:'POST',body:JSON.stringify({message})});await renderCommunityChat(id)}catch(err){toast(err.message,'error')}}}

function openFeedback(bookingId){const booking=bookings.find(b=>b.id===bookingId);if(!booking||booking.status!=='completed'||booking.feedback_submitted)return;$('#feedback-form').reset();$('#feedback-form [name=booking_id]').value=bookingId;$('#feedback-dialog').showModal()}
function openBookingDetails(row){const isFamily=me.role==='family',isContributor=me.role==='contributor',canPay=row.booked_by_me!==false;let buttons='';if(isFamily&&!['completed','cancelled','unfilled'].includes(row.status))buttons+=`<button class="outline-button" data-cancel="${esc(row.id)}">Cancel booking</button>`;if(isFamily&&row.payment_state==='unpaid'){if(canPay)buttons+=providerStatus.razorpay?.configured?`<button class="button primary" data-pay="${esc(row.id)}">Pay securely in app · ₹${row.price_inr}</button>`:'<span class="status-pill status-pending">In-app payments are not configured yet</span>';else buttons+='<span class="status-pill status-pending">The account that placed this booking needs to complete payment.</span>'}if(isFamily&&row.payment_state==='paid'&&['confirmed','in_progress'].includes(row.status))buttons+=`<div class="session-code"><b>Give this code to the helper at arrival</b><strong>${esc(row.arrival_code||'Unavailable')}</strong></div><div class="session-code"><b>Give this separate code before the helper leaves</b><strong>${esc(row.departure_code||'Unavailable')}</strong></div>`;if(isContributor&&row.status==='confirmed')buttons+=`<button class="outline-button" data-checkin="${esc(row.id)}">Confirm arrival using client code</button>`;if(isContributor&&row.status==='in_progress')buttons+=`<button class="button primary" data-checkout="${esc(row.id)}">Confirm departure using client code</button>`;if(isFamily&&row.status==='completed'&&!row.feedback_submitted)buttons+=`<button class="outline-button" data-feedback="${esc(row.id)}">Rate this accompaniment</button>`;const helper=row.helper?`<section class="panel voice-panel"><div class="panel-heading"><div><h3>Your helper</h3><p>${esc(row.helper.name)}</p></div><b>${row.helper.average_rating===null?'No ratings yet':`★ ${row.helper.average_rating} / 5 · ${row.helper.rating_count} rating${row.helper.rating_count===1?'':'s'}`}</b></div>${row.helper.phone?`<a class="button primary" href="tel:${esc(row.helper.phone.replace(/[^+0-9]/g,''))}">☎ Call ${esc(row.helper.phone)}</a>`:'<p>Phone number is not available.</p>'}</section>`:'';const acceptedNote=row.helper_accepted&&row.payment_state!=='paid'?'<p class="alert-guidance">The helper accepted this request. The visit is confirmed after the booking customer completes in-app payment.</p>':'';$('#detail-content').innerHTML=`<div class="booking-detail"><div class="modal-heading"><div><span class="eyebrow">VISIT · ${esc(row.id)}</span><h2>${esc(row.category)}</h2><p>${esc(row.person)} · ${esc(dateLabel(row.service_date))} at ${esc(timeLabel(row.start_time))}</p></div><button class="close-button" data-close-dialog="detail-dialog">×</button></div><div class="person-details"><div><span>Status</span><b>${esc(row.status)}</b></div><div><span>Area</span><b>${esc(row.service_area)}</b></div><div><span>Duration</span><b>${row.duration_hours} hours</b></div><div><span>Fare</span><b>₹${row.price_inr}</b></div><div><span>Payment</span><b>${esc(row.payment_state)}</b></div></div>${helper}${acceptedNote}<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px">${buttons}<button class="outline-button" data-incident-booking="${esc(row.id)}">Report incident</button></div><p class="alert-meta">The helper confirms arrival and departure with separate one-time codes. A visit cannot start until payment is captured.</p></div>`;$('#detail-dialog').showModal()}

async function renderHelpdesk(){const view=$('#view-messages'),contact=await api('/api/helpdesk'),helper=me.role==='contributor';view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">${helper?'HELPER SUPPORT':'DIRECT SUPPORT'}</div><h1>Help & support</h1><p>${helper?'Call the coordinator or emergency services directly.':'Call the care helpdesk directly for booking or account support.'}</p></div>${helper?'<button type="button" class="button primary" data-go="bookings">Browse available gigs →</button>':''}</div><div class="help-contact-grid"><section class="panel voice-panel help-contact-card"><div class="panel-heading"><div><h2>${esc(contact.name)}</h2><p>${esc(contact.hours||'Service hours not configured')}</p></div></div>${contact.phone?`<a class="button primary call-helpdesk" href="tel:${esc(contact.phone.replace(/[^+0-9]/g,''))}">☎ Call helpdesk · ${esc(contact.phone)}</a>`:'<p class="provider-state">Helpdesk phone is not configured for this deployment.</p>'}${contact.email?`<p><a href="mailto:${esc(contact.email)}">Email ${esc(contact.email)}</a></p>`:''}</section><section class="panel voice-panel emergency-help"><h2>Emergency contacts</h2><p>For immediate danger, call emergency services. CareCircle is not an emergency response service.</p><a class="button red-button" href="tel:112">☎ Call 112 · Emergency services</a><a class="button outline-button" href="tel:108">☎ Call 108 · Ambulance</a><small>Ambulance availability through 108 varies by state. If unavailable, call 112.</small></section></div>${contact.configured?'':'<p class="assumption-note">Set HELPDESK_PHONE, HELPDESK_EMAIL, and HELPDESK_HOURS in deployment settings to show your care-team contact details.</p>'}`}
async function renderIntegrations(){if(me.role==='family'||me.role==='contributor')return renderHelpdesk();const view=$('#view-messages');if(!view)return;if(me.role==='family'){const history=await api('/api/messages');view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">CLIENT SUPPORT · HUMAN FOLLOW-UP</div><h1>Talk to the care team</h1><p>Send a message in your preferred language. A person reviews it; urgent reports are not handled automatically.</p></div></div><div class="alert-guidance"><span>ⓘ</span><p><b>Immediate danger?</b> Call 112 now. CareCircle is not an emergency service.</p></div><section class="panel voice-panel"><div class="panel-heading"><div><h2>Send a report or ask for help</h2><p>${profiles.length?'Your note will be securely recorded for the care team.':'Create your client profile first to send a report.'}</p></div></div>${profiles.length?`<form id="client-report-form" class="form-grid"><label>Care profile<select name="profile_id">${profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.display_name)}</option>`).join('')}</select></label><label>Preferred language<select name="language">${[...new Set(profiles.map(p=>p.language))].map(x=>`<option>${esc(x)}</option>`).join('')}<option>Other</option></select></label><label>What is this about?<select name="category"><option>General support</option><option>Request a walk or visit</option><option>Medical concern</option><option>Fall</option><option>Safety concern</option><option>Possible money scam</option><option>Medication reminder</option></select></label><label>Priority<select name="severity"><option value="routine">Routine · follow up</option><option value="yellow">Needs attention</option><option value="red">Urgent · human follow-up</option></select></label><label class="full-field">Your message<textarea name="description" minlength="5" maxlength="3000" required placeholder="You can write in your preferred language. Do not include passwords or payment details."></textarea></label><div class="full-field"><button class="button primary">Send to care team</button></div></form>`:`<button class="button primary" data-go="people">Create my care profile</button>`}</section><section class="panel voice-panel"><div class="panel-heading"><div><h2>Audio and WhatsApp</h2><p>${esc(providerStatus.whatsapp?.configured?'WhatsApp is configured; availability depends on approved recipients and templates.':'WhatsApp audio intake is not connected yet. Send a written note here, or call 112 for immediate danger.')}</p></div><span class="provider-state ${providerStatus.whatsapp?.configured?'ready':''}">${providerStatus.whatsapp?.configured?'CONFIGURED':'NOT CONNECTED'}</span></div><p class="integrations-help">Speech transcription, translation, and WhatsApp delivery require external credentials and consent. This page never claims an audio was received when it was not.</p></section><section class="panel voice-panel"><div class="panel-heading"><div><h2>Your recent messages</h2><p>Delivery and human review status</p></div><button class="outline-button" id="refresh-client-messages">Refresh</button></div>${history.length?history.map(m=>`<article class="attention-item"><div class="severity-mark">◉</div><div class="attention-copy"><b>${esc(m.intent||m.kind)} · ${esc(m.status.replaceAll('_',' '))}</b><span>${esc(m.transcript||'Audio received; transcript unavailable')}<br>${new Date(m.received_at).toLocaleString()}</span></div></article>`).join(''):'<p class="empty-state">No messages yet.</p>'}</section>`;$('#client-report-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const button=e.currentTarget.querySelector('button[type="submit"],button:not([type])');button.disabled=true;try{const result=await api('/api/client/reports',{method:'POST',body:JSON.stringify(Object.fromEntries(f.entries()))});toast(result.status==='received_for_human_review'?'Your message was sent to the care team for human review.':'Your message was sent.');if(result.emergency_guidance)toast(result.emergency_guidance,'warning');await renderIntegrations();await refreshCommon()}catch(err){toast(err.message,'error');button.disabled=false}});const audioProfiles=profiles.filter(p=>p.voice_ai_consent);const voiceBox=document.createElement('section');voiceBox.className='panel voice-panel';voiceBox.innerHTML=`<div class="panel-heading"><div><h2>Send an audio message</h2><p>Audio is processed only with profile consent and configured speech providers. A human reviews every result.</p></div><span class="provider-state ${providerStatus.voice_ai?.configured?'ready':''}">${providerStatus.voice_ai?.configured?'READY':'NOT CONNECTED'}</span></div>${audioProfiles.length?`<form id="client-voice-form" class="form-grid"><label>Care profile<select id="voice-profile">${audioProfiles.map(p=>`<option value="${esc(p.id)}">${esc(p.display_name)} · ${esc(p.language)}</option>`).join('')}</select></label><label>Audio message<input id="voice-file" type="file" accept="audio/ogg,audio/opus,audio/mp3,audio/mpeg,audio/mp4,audio/wav,audio/webm" required></label><label class="full-field consent-check"><input id="voice-consent-check" type="checkbox" required><span>I confirm this person agreed to send this recording for external speech processing.</span></label><div class="full-field"><button class="button primary" ${providerStatus.voice_ai?.configured?'':'disabled'}>${providerStatus.voice_ai?.configured?'Send for transcription and human review':'Speech providers are not configured'}</button></div></form><div id="voice-result" class="voice-result"></div>`:`<p class="empty-state">Turn on external voice processing consent in My care & data to enable audio. ${providerStatus.voice_ai?.configured?'':'Speech providers still need configuration.'}</p>`}`;view.querySelector('.page-heading').after(voiceBox);$('#client-voice-form')?.addEventListener('submit',submitVoice);$('#refresh-client-messages').onclick=()=>renderIntegrations().catch(e=>toast(e.message,'error'));return}const providers=providerStatus;view.innerHTML=`<div class="page-heading"><div><div class="eyebrow">PROVIDER STATUS · SERVER CONFIGURATION</div><h1>${me.role==='operator'?'Message review & integrations':'Support & connections'}</h1><p>Unconfigured providers are blocked and cannot create fake success states.</p></div><button class="outline-button" id="refresh-providers">Refresh status</button></div><div class="integration-grid">${Object.entries(providers).map(([key,p])=>`<article class="integration-card"><h3>${esc(key.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()))}</h3><p>${esc(p.status)}</p><span class="provider-state ${p.configured?'ready':''}">${p.configured?'CONFIGURED':'BLOCKED'}</span></article>`).join('')}</div><div class="panel voice-panel"><div class="panel-heading"><div><h2>Voice request intake</h2><p>Audio is sent to the configured speech and language providers only after explicit profile consent.</p></div></div><form id="voice-form" class="form-grid"><label>Consented profile<select id="voice-profile">${profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.display_name)} · ${esc(p.language)}</option>`).join('')}</select></label><label>Audio file<input id="voice-file" type="file" accept="audio/ogg,audio/mp3,audio/mpeg,audio/mp4,audio/wav,audio/webm" required></label><label class="full-field consent-check"><input id="voice-consent-check" type="checkbox" required><span>I confirm this profile has explicitly consented to external speech-to-text and language processing.</span></label><div class="full-field"><button class="button primary" ${profiles.length&&providerStatus.voice_ai?.configured?'':'disabled'}>${providerStatus.voice_ai?.configured?'Transcribe & classify for human confirmation':'Voice providers are not configured'}</button></div></form><div id="voice-result" class="voice-result"></div><p class="integrations-help">Voice requests are never booked automatically. Original-language transcription and proposed intent are returned for confirmation; urgent language follows human review.</p></div><div class="disclaimer">Provider availability does not itself confirm account approval, device support, successful delivery, or legal readiness.</div>`;$('#refresh-providers').onclick=async()=>{providerStatus=(await api('/api/system/status')).providers;renderIntegrations()};$('#voice-form').onsubmit=submitVoice;await renderNotificationQueue();await renderMessageReview()}
async function renderNotificationQueue(){const old=$('#notification-retry-queue');if(me.role!=='operator'){old?.remove();return}const queues=await api('/api/admin/queue');const items=queues.retryable_notifications||[];const panel=document.createElement('section');panel.id='notification-retry-queue';panel.className='panel';panel.style.margin='14px 0';panel.innerHTML=`<div class="panel-heading"><div><h2>Blocked delivery queue</h2><p>Retry only after the provider or recipient issue has been corrected.</p></div></div>${items.length?items.map(n=>`<article class="attention-item"><div class="severity-mark yellow">↻</div><div class="attention-copy"><b>${esc(n.message_type)} · ${esc(n.status)}</b><span>${esc(n.last_error||'Delivery did not complete')} · attempts ${n.attempts}</span><button data-retry-notification="${esc(n.id)}">Queue retry →</button></div></article>`).join(''):'<p class="empty-state">No blocked or failed notifications.</p>'}`;const anchor=$('.voice-panel');if(old)old.replaceWith(panel);else if(anchor)anchor.before(panel)}
async function renderMessageReview(){const old=$('#message-review-queue');if(me.role!=='operator'){old?.remove();return}const messages=await api('/api/messages');const pending=messages.filter(m=>m.status==='human_review');const panel=document.createElement('section');panel.id='message-review-queue';panel.className='panel';panel.style.margin='14px 0';panel.innerHTML=`<div class="panel-heading"><div><h2>Human message review</h2><p>Review the original-language transcript and add a note before closing the queue item.</p></div></div>${pending.length?pending.map(m=>`<article class="attention-item"><div class="severity-mark">${m.intent==='urgent'?'!':'◉'}</div><div class="attention-copy"><b>${esc(m.intent||'unclear')} · ${esc(m.kind||'message')}</b><span>${esc(m.transcript||'No transcript available')}<br>${new Date(m.received_at).toLocaleString()}</span><button data-review-message="${esc(m.id)}">Record review →</button></div></article>`).join(''):'<p class="empty-state">No messages need human review.</p>'}`;const anchor=$('.voice-panel');if(old)old.replaceWith(panel);else if(anchor)anchor.before(panel)}

function openNotificationContact(profileId){const p=profiles.find(x=>x.id===profileId);if(!p)return;$('#notification-contact-form').reset();$('#contact-profile-id').value=p.id;$('#contact-elder-phone').value=p.phone||'';$('#contact-elder-whatsapp').value=p.whatsapp_id||'';$('#contact-name').value=p.notification_name||'';$('#contact-relationship').value=p.notification_relationship||'';$('#contact-phone').value=p.notification_phone||'';$('#contact-consent').checked=Boolean(p.notification_contact_consent);$('#notification-contact-dialog').showModal()}
document.body.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-notifications]');if(edit)openNotificationContact(edit.dataset.editNotifications)});
document.body.addEventListener('click',e=>{const verify=e.target.closest('[data-verify-profile]');if(verify){identityProfilePrefill=verify.dataset.verifyProfile;showView('verification')}});
$('#notification-contact-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button[type="submit"],button:not([type])');button.disabled=true;try{await api(`/api/profiles/${encodeURIComponent($('#contact-profile-id').value)}/notification-contact`,{method:'PATCH',body:JSON.stringify({elder_phone:$('#contact-elder-phone').value,elder_whatsapp_id:$('#contact-elder-whatsapp').value||null,notification_name:$('#contact-name').value,notification_relationship:$('#contact-relationship').value,notification_phone:$('#contact-phone').value,notification_contact_consent:$('#contact-consent').checked})});$('#notification-contact-dialog').close();toast('Elder and notification contact details updated.');await refresh()}catch(err){toast(err.message,'error');button.disabled=false}});
async function updateBookingFare(){const duration=Number($('#booking-duration').value||1);try{const quote=await api(`/api/bookings/fare?duration_hours=${duration}`);$('#booking-fare').value=quote.suggested_fare_inr;$('#booking-payout-estimate').textContent=`Suggested visit fare ₹${quote.suggested_fare_inr}. Helper payout estimate ₹${Math.round(quote.suggested_fare_inr*240/300)}. Final amount is charged in app.`}catch(err){toast(err.message,'error')}}
async function openBooking(){try{$('#booking-form').reset();$('#booking-fare').value=300;$('#booking-payout-estimate').textContent='Suggested visit fare ₹300 for 1 hour. You can change the fare before continuing.';if(!profiles.length){toast('Create an elder profile first.','warning');showView('people');return}$('#booking-person').innerHTML=profiles.filter(p=>p.family_access&&p.verification==='verified').map(p=>`<option value="${esc(p.id)}">${esc(p.display_name)}</option>`).join('');if(!$('#booking-person').options.length){toast('Complete identity and relationship verification before booking.','warning');showView('verification');return}const tomorrow=new Date(`${indiaDate()}T12:00:00Z`);tomorrow.setUTCDate(tomorrow.getUTCDate()+1);$('#booking-date').value=tomorrow.toISOString().slice(0,10);$('#booking-dialog').showModal();await updateBookingFare()}catch(err){toast(err.message||'Could not open the visit request form. Please try again.','error')}}
$('#booking-duration').addEventListener('change',updateBookingFare);$('#booking-fare').addEventListener('input',()=>{const fare=Number($('#booking-fare').value||0);$('#booking-payout-estimate').textContent=`Helper payout estimate ₹${Math.round(fare*240/300)}. You will pay this fare in the app; no cash collection is arranged.`});
$('#new-booking').addEventListener('click',e=>{e.preventDefault();openBooking()});$('#new-booking-2').addEventListener('click',e=>{e.preventDefault();openBooking()});
$('#booking-form').addEventListener('submit',async e=>{e.preventDefault();const button=$('#save-booking');button.disabled=true;try{const res=await api('/api/bookings',{method:'POST',body:JSON.stringify({profile_id:$('#booking-person').value,category:$('#booking-type').value,service_date:$('#booking-date').value,start_time:$('#booking-time').value,duration_hours:Number($('#booking-duration').value),fare_inr:Number($('#booking-fare').value),language:profiles.find(p=>p.id===$('#booking-person').value)?.language||'English',instructions:$('#booking-instructions').value})});$('#booking-dialog').close();toast(`Visit request saved · fare ₹${res.price_inr}. Pay in app to confirm.`,'warning');await refresh();showView('bookings');const item=bookings.find(b=>b.id===res.id);if(item)openBookingDetails(item)}catch(err){toast(err.message,'error')}finally{button.disabled=false}});

$('#add-person').onclick=()=>{$('#profile-form').reset();$('#profile-dialog h2').textContent=me.role==='family'?(me.account_type==='elder'?'Update my care profile':'Add an elder care profile'):'Add a care profile';$('#profile-dialog').showModal()};
$('#new-red-alert').onclick=async()=>{if(!profiles.length){toast('Add a consented care profile before creating an alert.','warning');showView('people');return}const title=prompt('Describe the urgent event for human follow-up:');if(!title)return;try{await api('/api/admin/alerts',{method:'POST',body:JSON.stringify({profile_id:profiles[0].id,category:'red',title,source:'operator_report'})});toast('Urgent alert entered in the operator queue.');await refresh();showView('alerts')}catch(err){toast(err.message,'error')}};
$('#profile-dialog').addEventListener('close',()=>$('#profile-form').reset());
$('#booking-dialog').addEventListener('close',()=>$('#booking-form').reset());
$('#community-request-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit],button:not([type])'),data=Object.fromEntries(new FormData(form).entries());button.disabled=true;try{await api('/api/communities/requests',{method:'POST',body:JSON.stringify(data)});$('#community-request-dialog').close();toast('Community request sent for operator review.');await renderCommunity()}catch(err){toast(err.message,'error')}finally{button.disabled=false}});
$('#feedback-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit],button:not([type])'),id=form.elements.booking_id.value,data={rating:Number(form.elements.rating.value),comment:form.elements.comment.value};button.disabled=true;try{await api(`/api/bookings/${encodeURIComponent(id)}/feedback`,{method:'POST',body:JSON.stringify(data)});$('#feedback-dialog').close();feedbackPrompted.delete(id);toast('Thank you for rating the accompaniment.');await refresh()}catch(err){toast(err.message,'error')}finally{button.disabled=false}});
$('#reminder-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button'),data=Object.fromEntries(new FormData(form).entries());data.due_at=new Date(data.due_at).toISOString();button.disabled=true;try{await api('/api/reminders',{method:'POST',body:JSON.stringify(data)});form.elements.title.value='';toast('Reminder saved.');await renderReminders()}catch(err){toast(err.message,'error')}finally{button.disabled=false}});$('#refresh-reminders').addEventListener('click',renderReminders);
document.body.addEventListener('click',e=>{if(e.target.closest('[data-back-community]')){showView('community');return}});
document.body.addEventListener('click',async e=>{const button=e.target.closest('[data-cancel-reminder]');if(!button)return;button.disabled=true;try{await api(`/api/reminders/${encodeURIComponent(button.dataset.cancelReminder)}/cancel`,{method:'POST',body:'{}'});toast('Reminder cancelled.');await renderReminders()}catch(err){toast(err.message,'error');button.disabled=false}});
$('#profile-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const data=Object.fromEntries(f.entries());for(const k of ['consent_confirmed','family_access','monitoring_consent','voice_ai_consent','notification_contact_consent'])data[k]=f.has(k);data.age=data.age?Number(data.age):null;data.retention_days=Number(data.retention_days||30);try{const p=await api('/api/profiles',{method:'POST',body:JSON.stringify(data)});$('#profile-dialog').close();toast(`${p.display_name} profile created with consent.`);await refresh();showView('people')}catch(err){toast(err.message,'error')}});

function updateRegistrationFields(){const register=$('#auth-title').dataset.mode==='register',type=$('#auth-role').value,isCare=['guardian','elder'].includes(type),fields=$('#client-profile-setup'),elder=type==='elder';fields.disabled=!register||!isCare;fields.classList.toggle('hidden',!register||!isCare);$('#account-type').value=elder?'elder':'guardian';const rel=$('#account-relationship-field'),relInput=rel.querySelector('input'),elderFields=$('#elder-signup-fields');rel.classList.toggle('hidden',elder);relInput.disabled=elder||!register||!isCare;relInput.required=!elder&&register&&isCare;elderFields.classList.toggle('hidden',!elder||!register);elderFields.querySelectorAll('input,select,textarea').forEach(control=>control.disabled=!register||!elder);const admin=register&&type==='operator',adminField=$('#admin-invite-field'),adminInput=$('#admin-invite-code'),adminHelp=$('#admin-invite-help');adminField.classList.toggle('hidden',!admin);adminHelp.classList.toggle('hidden',!admin);adminInput.disabled=!admin;adminInput.required=admin;const needsPhone=register&&['contributor','operator'].includes(type),phoneField=$('#signup-phone-field'),phoneInput=$('#signup-phone');phoneField.classList.toggle('hidden',!needsPhone);phoneInput.disabled=!needsPhone;phoneInput.required=needsPhone}

$('#auth-role').addEventListener('change',updateRegistrationFields);
function setAuthMode(register){$('#auth-title').dataset.mode=register?'register':'login';$('#auth-email').required=!register;$('#auth-email').placeholder=register?'Email address (optional)':'Email address or phone number';$('#auth-title').textContent=register?'Create your account':'Welcome back';$('#auth-copy').textContent=register?'Create a gig worker account or sign in as an organisation admin.':'Sign in as an organisation admin or gig worker.';$('#auth-submit').textContent=register?'Create account':'Sign in';$('#mode-sign-in').classList.toggle('selected',!register);$('#mode-create').classList.toggle('selected',register);$('#mode-sign-in').setAttribute('aria-selected',String(!register));$('#mode-create').setAttribute('aria-selected',String(register));$('#role-field').classList.toggle('hidden',!register);$('#auth-password').autocomplete=register?'new-password':'current-password';updateRegistrationFields();showError('#auth-error','')}
$('#mode-sign-in').onclick=()=>setAuthMode(false);$('#mode-create').onclick=()=>setAuthMode(true);$('#auth-toggle').onclick=()=>setAuthMode($('#auth-title').dataset.mode!=='register');
$('#auth-form').onsubmit=async e=>{e.preventDefault();const registering=$('#auth-title').dataset.mode==='register';showError('#auth-error','');try{if(registering){const selected='contributor',isCare=false,role='contributor',payload={email:$('#auth-email').value.trim()||null,password:$('#auth-password').value,role};if(['contributor','operator'].includes(selected))payload.phone=$('#signup-phone').value;if(role==='operator')payload.admin_invite_code=$('#admin-invite-code').value;if(isCare){const f=new FormData($('#client-profile-setup'));payload.family_account={name:f.get('account_name'),relationship:selected==='elder'?'Self':f.get('account_relationship'),phone:f.get('account_phone'),account_type:selected};if(selected==='elder')payload.client_profile={display_name:f.get('display_name'),age:f.get('age')?Number(f.get('age')):null,phone:f.get('phone'),whatsapp_id:f.get('whatsapp_id')||null,language:f.get('language'),city:f.get('city'),service_area:f.get('service_area'),notification_name:f.get('notification_name'),notification_relationship:f.get('notification_relationship'),notification_phone:f.get('notification_phone'),notification_contact_consent:f.has('notification_contact_consent'),family_access:f.has('family_access'),monitoring_consent:f.has('monitoring_consent'),voice_ai_consent:f.has('voice_ai_consent'),consent_confirmed:f.has('consent_confirmed')}}const result=await api('/api/auth/register',{method:'POST',skipCsrf:true,body:JSON.stringify(payload)});if(!payload.email)$('#auth-email').value=$('#signup-phone').value;setAuthMode(false);$('#auth-title').textContent='Account created';$('#auth-copy').textContent=result.role==='operator'?'Main admin account created. Sign in to open the admin panel.':result.account_type==='guardian'?'Guardian account created. Sign in to add the elder profile, then complete verification.':result.account_type==='elder'?'Elder account and care profile created. Sign in to continue.':'Helper account created. Sign in to complete contributor onboarding.';$('#auth-submit').textContent='Sign in';$('#role-field').classList.add('hidden');$('#admin-invite-field').classList.add('hidden');$('#auth-toggle').textContent='Create another account';updateRegistrationFields();toast('Account profile created. Sign in to continue.')}else{const res=await api('/api/auth/login',{method:'POST',skipCsrf:true,body:JSON.stringify({email:$('#auth-email').value,password:$('#auth-password').value})});csrf=res.csrf_token;await hydrate()}}catch(err){showError('#auth-error',err.message)}};
$('#sign-out').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});location.reload()}catch(e){toast(e.message,'error')}};
$('#header-avatar').onclick=()=>showView('profile');
$('#mini-avatar').onclick=()=>showView('profile');
$('#go-back').onclick=()=>{const fallback=me?.role==='operator'?'analytics':'overview';if(history.length>1&&history.state?.view)history.back();else showView(fallback)};

$('#availability-toggle').onclick=async()=>{try{const c=await api('/api/contributor');const res=await api('/api/contributor/availability',{method:'PATCH',body:JSON.stringify({available:!c.availability})});toast(res.availability?'Availability is on.':'Availability paused.');await refresh()}catch(e){toast(e.message,'error')}};
document.addEventListener('submit',async e=>{if(e.target.id==='onboarding-form'){e.preventDefault();const f=new FormData(e.target);const data={display_name:f.get('display_name'),address:f.get('address'),date_of_birth:f.get('date_of_birth'),profession:f.get('profession'),identity_document_type:f.get('identity_document_type'),identity_mode:f.get('identity_mode'),identity_reference:f.get('identity_reference'),identity_consent:f.has('identity_consent'),city:f.get('city'),service_area:f.get('service_area'),languages:f.get('languages').split(',').map(x=>x.trim()).filter(Boolean),tasks:f.getAll('task').map(x=>String(x).trim().toLowerCase()).filter(Boolean)};showError('#onboarding-error','');if(!data.tasks.length){showError('#onboarding-error','Choose at least one type of work.');return}try{await api('/api/contributor/onboarding',{method:'POST',body:JSON.stringify(data)});toast('Worker profile submitted for admin review.');await renderMyProfile()}catch(err){showError('#onboarding-error',err.message);toast(err.message,'error')}}});

document.body.addEventListener('click',async e=>{const nav=e.target.closest('.nav-item[data-view]');if(nav){showView(nav.dataset.view);return}const commOpen=e.target.closest('[data-community-open]');if(commOpen){selectedCommunity=commOpen.dataset.communityOpen;showView('community-chat');return}const commJoin=e.target.closest('[data-community-join]');if(commJoin){try{await api(`/api/communities/${encodeURIComponent(commJoin.dataset.communityJoin)}/join`,{method:'POST',body:'{}'});await renderCommunity();toast('You joined the community.')}catch(err){toast(err.message,'error')}return}const commReview=e.target.closest('[data-community-review]');if(commReview){let note='';if(commReview.dataset.decision==='reject'){note=prompt('Reason for declining this request:')||'';if(note.trim().length<5)return}try{await api(`/api/communities/requests/${encodeURIComponent(commReview.dataset.communityReview)}/review`,{method:'POST',body:JSON.stringify({decision:commReview.dataset.decision,note})});toast('Community request reviewed.');await renderCommunity()}catch(err){toast(err.message,'error')}return}const filter=e.target.closest('[data-booking-filter]');if(filter){bookingFilter=filter.dataset.bookingFilter;renderBookings();return}const go=e.target.closest('[data-go]');if(go){showView(go.dataset.go);return}const preview=e.target.closest('[data-task-preview]');if(preview){openGigPreview(preview.dataset.taskPreview);return}const b=e.target.closest('[data-booking],[data-accept],[data-ignore],[data-progress],[data-ack],[data-resolve],[data-alert-review],[data-reminder-profile],[data-monitor-profile],[data-cancel],[data-checkin],[data-checkout],[data-feedback],[data-pay],[data-incident-booking],[data-close-dialog]');if(!b)return;try{if(b.dataset.closeDialog){(b.dataset.closeDialog==='parent'?b.closest('dialog'):document.getElementById(b.dataset.closeDialog))?.close();return}if(b.dataset.booking){const row=bookings.find(x=>x.id===b.dataset.booking);if(row)openBookingDetails(row);return}
 if(b.dataset.accept){await api(`/api/bookings/${encodeURIComponent(b.dataset.accept)}/accept`,{method:'POST',body:'{}'});$('#gig-preview-dialog')?.close();toast('Task accepted. Client contact and visit details are now available.');await refresh();return}
 if(b.dataset.ignore){await api(`/api/bookings/${encodeURIComponent(b.dataset.ignore)}/ignore`,{method:'POST',body:'{}'});$('#gig-preview-dialog')?.close();toast('Task ignored.');await refresh();return}
 if(b.dataset.progress){const completion_code=b.dataset.status==='done'?prompt('Enter the client or organisation completion code:'):undefined;if(b.dataset.status==='done'&&!completion_code)return;await api(`/api/bookings/${encodeURIComponent(b.dataset.progress)}/progress`,{method:'POST',body:JSON.stringify({status:b.dataset.status,completion_code})});$('#gig-preview-dialog')?.close();toast('Task progress saved and organisation notified.');await refresh();return}
 if(b.dataset.ack){await api(`/api/alerts/${encodeURIComponent(b.dataset.ack)}/acknowledge`,{method:'POST',body:'{}'});toast('Alert acknowledged and assigned to you.');await refresh();return}
 if(b.dataset.resolve){const note=prompt('Enter the human review and response record:');if(!note)return;await api(`/api/alerts/${encodeURIComponent(b.dataset.resolve)}/resolve`,{method:'POST',body:JSON.stringify({response_note:note})});toast('Alert resolution recorded.');await refresh();return}
 if(b.dataset.alertReview){showView('alerts');return}
 if(b.dataset.reminderProfile){reminderProfilePrefill=b.dataset.reminderProfile;showView('reminders');return}
 if(b.dataset.monitorProfile){const response=await api(`/api/integrations/fitbit/connect?profile_id=${encodeURIComponent(b.dataset.monitorProfile)}`);location.href=response.authorization_url;return}
 if(b.dataset.cancel){await api(`/api/bookings/${encodeURIComponent(b.dataset.cancel)}/cancel`,{method:'POST',body:'{}'});$('#detail-dialog').close();toast('Cancellation and replacement search recorded.');await refresh();return}
 if(b.dataset.checkin){const otp=prompt('Enter check-in OTP supplied by the customer:');if(!otp)return;await api(`/api/bookings/${encodeURIComponent(b.dataset.checkin)}/check-in`,{method:'POST',body:JSON.stringify({otp})});$('#detail-dialog').close();toast('Check-in verified.');await refresh();return}
 if(b.dataset.checkout){const otp=prompt('Enter separate check-out OTP supplied by the customer:');if(!otp)return;await api(`/api/bookings/${encodeURIComponent(b.dataset.checkout)}/check-out`,{method:'POST',body:JSON.stringify({otp})});$('#detail-dialog').close();toast('Session completed. Payout state is pending settlement.');await refresh();return}
 if(b.dataset.feedback){openFeedback(b.dataset.feedback);return}
 if(b.dataset.pay){await startPayment(b.dataset.pay);return}
 if(b.dataset.incidentBooking){const category=prompt('Incident category, e.g. fall, safety, complaint:');if(!category)return;const description=prompt('Describe what happened:');if(!description)return;await api('/api/incidents',{method:'POST',body:JSON.stringify({booking_id:b.dataset.incidentBooking,category,description})});toast('Incident filed for operator follow-up.');$('#detail-dialog').close();return}
 }catch(err){toast(err.message,'error')}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-worker-action]');if(!b)return;const id=b.dataset.workerId,action=b.dataset.workerAction;let body={};if(action==='identity'){if(b.dataset.workerMode!=='authorized_provider'){toast('Sandbox identity results cannot be treated as verified.','warning');return}body.identity_state='approved'}if(action==='approve')body.approval_state='approved';if(action==='reject')body.approval_state='rejected';if(action==='training')body.training_complete=b.dataset.workerValue==='true';if(action==='account')body.active=b.dataset.workerValue==='true';b.disabled=true;try{const result=await api(`/api/admin/contributors/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(body)});toast(action==='training'?`Training marked ${result.training_complete?'Completed':'Not Completed'}.`:action==='account'?`Worker account ${result.active?'reactivated':'suspended'}.`:'Worker review saved.');await renderPeople();await updateSummaryCards()}catch(err){toast(err.message,'error');b.disabled=false}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-incident-resolution]');if(!b)return;const resolution=prompt('Describe the operator response and resolution:');if(!resolution)return;try{await api(`/api/admin/incidents/${encodeURIComponent(b.dataset.incidentResolution)}/resolve`,{method:'POST',body:JSON.stringify({resolution})});toast('Incident resolution recorded.');await renderIncidentQueue()}catch(err){toast(err.message,'error')}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-identity-review]');if(!b)return;let review_note='';if(b.dataset.status==='rejected'){review_note=prompt('What needs to be corrected?')||'';if(review_note.trim().length<5)return}b.disabled=true;try{await api(`/api/admin/identity-verifications/${encodeURIComponent(b.dataset.identityReview)}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.status,review_note})});toast(`Verification marked ${b.dataset.status}.`);await renderIdentityVerificationQueue()}catch(err){toast(err.message,'error');b.disabled=false}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-review-message]');if(!b)return;const note=prompt('Record the human review note:');if(!note||note.trim().length<4)return;try{await api(`/api/admin/messages/${encodeURIComponent(b.dataset.reviewMessage)}/review`,{method:'POST',body:JSON.stringify({note})});toast('Message review recorded.');await renderMessageReview()}catch(err){toast(err.message,'error')}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-exception-complete]');if(!b)return;const reason=prompt('Document the human confirmation or other completion-code exception (minimum 10 characters):');if(!reason||reason.trim().length<10)return;try{await api(`/api/admin/gigs/${encodeURIComponent(b.dataset.exceptionComplete)}/complete-exception`,{method:'POST',body:JSON.stringify({reason})});toast('Completion exception recorded in the audit history.');await renderAdminGigQueue();await renderAdminEarnings();await renderOrganizationNotifications()}catch(err){toast(err.message,'error')}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-mark-earning-paid]');if(!b)return;const payment_reference=prompt('Enter the actual payout settlement reference:');if(!payment_reference||payment_reference.trim().length<3)return;try{await api(`/api/admin/earnings/${encodeURIComponent(b.dataset.markEarningPaid)}/mark-paid`,{method:'POST',body:JSON.stringify({payment_reference})});toast('Payout settlement recorded.');await renderAdminEarnings();await renderOrganizationNotifications()}catch(err){toast(err.message,'error')}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-org-notification-read]');if(!b)return;try{await api(`/api/admin/notifications/${encodeURIComponent(b.dataset.orgNotificationRead)}/read`,{method:'POST',body:'{}'});await renderOrganizationNotifications()}catch(err){toast(err.message,'error')}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-retry-notification]');if(!b)return;try{await api(`/api/admin/notifications/${encodeURIComponent(b.dataset.retryNotification)}/retry`,{method:'POST',body:'{}'});toast('Notification returned to the worker queue.');await renderNotificationQueue()}catch(err){toast(err.message,'error')}});

$('#quick-alert').onclick=async()=>{if(!profiles.length){toast('Create a consented profile before recording an alert.','warning');return}const title=prompt('Alert title:');if(!title)return;try{await api('/api/admin/alerts',{method:'POST',body:JSON.stringify({profile_id:profiles[0].id,category:'yellow',title,source:'operator_report'})});toast('Alert created in the database.');await refresh()}catch(e){toast(e.message,'error')}};
async function submitVoice(e){e.preventDefault();const file=$('#voice-file').files[0],profile=$('#voice-profile').value;if(!file||!profile||!$('#voice-consent-check').checked)return;const form=new FormData();form.append('profile_id',profile);form.append('audio',file);$('#voice-result').classList.remove('error');$('#voice-result').textContent='Sending consented audio for transcription…';try{const result=await api('/api/voice/transcribe',{method:'POST',body:form});$('#voice-result').innerHTML=`<b>Original-language transcript:</b> ${esc(result.transcript_original)}<br><b>AI-drafted English translation:</b> ${result.translation_english?esc(result.translation_english):'Not available for this message'}<br><b>Proposed intent:</b> ${esc(result.intent.intent)} · human confirmation required. Booking created: no.`;await refresh()}catch(err){$('#voice-result').classList.add('error');$('#voice-result').textContent=err.message}}
async function startPayment(bookingId){const order=await api(`/api/bookings/${encodeURIComponent(bookingId)}/payments/order`,{method:'POST',body:'{}'});if(!window.Razorpay){await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://checkout.razorpay.com/v1/checkout.js';s.onload=resolve;s.onerror=reject;document.head.append(s)})}const checkout=new Razorpay({key:order.key_id,amount:order.amount,currency:order.currency,name:'CareCircle',description:'Care assistance booking',order_id:order.order_id,handler:async response=>{try{await api('/api/payments/verify',{method:'POST',body:JSON.stringify(response)});toast('Payment signature verified; awaiting provider webhook settlement.');await refresh()}catch(e){toast(e.message,'error')}},modal:{ondismiss:()=>toast('Payment checkout closed; status remains pending.','warning')}});checkout.open()}

$('#voice-form')?.addEventListener('submit',submitVoice);
document.addEventListener('change',async e=>{const consent=e.target.closest('[data-profile-consent]');if(consent){const field=consent.dataset.profileConsent,profileId=consent.dataset.profileId;consent.disabled=true;try{await api(`/api/profiles/${encodeURIComponent(profileId)}/consent`,{method:'PATCH',body:JSON.stringify({[field]:consent.checked})});toast('Consent preference updated.');await refresh()}catch(err){consent.checked=!consent.checked;toast(err.message,'error');consent.disabled=false}return}const review=e.target.closest('[data-identity-review]');if(review){const previous=review.dataset.current;review.disabled=true;try{const result=await api(`/api/admin/contributors/${encodeURIComponent(review.dataset.identityReview)}`,{method:'PATCH',body:JSON.stringify({identity_state:review.value})});toast(`Helper identity status set to ${result.identity_state}.`);renderPeople()}catch(err){review.value=previous;toast(err.message,'error');review.disabled=false}}});
document.addEventListener('DOMContentLoaded',async()=>{const oldHeader=$('.page-heading .eyebrow');if(oldHeader?.textContent.includes('SATURDAY'))oldHeader.textContent='LIVE OPERATIONS';try{await hydrate()}catch(e){if(e.status!==401){$('#auth-error').textContent=e.message||'Could not connect to the CareCircle service.'}}});
